-- READ-ONLY. Run on the intended database only after verifying DATABASE().
-- Duplicate groups expose user IDs rather than personal details. Do not commit results.
SELECT DATABASE() AS selected_database, VERSION() AS server_version;
SELECT COUNT(*) AS missing_or_blank_phone FROM users WHERE phone IS NULL OR TRIM(phone) = '';
SELECT COUNT(*) AS blank_email_to_review FROM users WHERE email IS NOT NULL AND TRIM(email) = '';
-- Exact/format-equivalent phone collisions. Kenya 07... / 2547... / +2547... map together.
SELECT COUNT(*) AS users_in_group, GROUP_CONCAT(id ORDER BY id) AS user_ids
FROM users WHERE CASE WHEN phone IS NULL OR REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '') = '' THEN NULL WHEN LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 4) = '+254' AND CHAR_LENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '')) = 13 THEN CONCAT('0', SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 5)) WHEN LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 3) = '254' AND CHAR_LENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '')) = 12 THEN CONCAT('0', SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 4)) ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '') END IS NOT NULL GROUP BY CASE WHEN phone IS NULL OR REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '') = '' THEN NULL WHEN LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 4) = '+254' AND CHAR_LENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '')) = 13 THEN CONCAT('0', SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 5)) WHEN LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 3) = '254' AND CHAR_LENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '')) = 12 THEN CONCAT('0', SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 4)) ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '') END HAVING COUNT(*) > 1;
-- Case/outer-whitespace-equivalent email collisions under the database collation.
SELECT COUNT(*) AS users_in_group, GROUP_CONCAT(id ORDER BY id) AS user_ids
FROM users WHERE LOWER(NULLIF(TRIM(email), '')) IS NOT NULL GROUP BY LOWER(NULLIF(TRIM(email), '')) HAVING COUNT(*) > 1;
-- Counts of rows that differ in presentation from their canonical identity;
-- review these, as changing a login identifier needs a deliberate migration plan.
SELECT SUM(CASE WHEN phone IS NOT NULL AND BINARY phone <> BINARY (CASE WHEN phone IS NULL OR REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '') = '' THEN NULL WHEN LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 4) = '+254' AND CHAR_LENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '')) = 13 THEN CONCAT('0', SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 5)) WHEN LEFT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 3) = '254' AND CHAR_LENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '')) = 12 THEN CONCAT('0', SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), ''), 4)) ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(phone), ' ', ''), '-', ''), '(', ''), ')', ''), CHAR(9), '') END) THEN 1 ELSE 0 END) AS noncanonical_phone_rows,
       SUM(CASE WHEN email IS NOT NULL AND BINARY email <> BINARY (LOWER(NULLIF(TRIM(email), ''))) THEN 1 ELSE 0 END) AS noncanonical_email_rows
FROM users;
-- Review existing indexes and generated columns before attempting DDL.
SHOW INDEX FROM users;
SHOW COLUMNS FROM users;
